frappe.ui.form.on("Delivery Note", {
	refresh(frm) {
		cannabis_management.metrc.setup_form(frm);
		if (frm.doc.docstatus === 0) cannabis_management.metrc.check_rows(frm);

		if (frm.doc.docstatus === 1 && frm.doc.custom_metrc_transfer_id) {
			frm.add_custom_button(
				__("Manifest PDF"),
				() => {
					frappe.msgprint({
						title: __("METRC Manifest"),
						message: __(
							"Manifest {0} is generated by METRC. Download it from the METRC portal — the API exposes it at /transfers/v2/manifest/{1}/pdf.",
							[frm.doc.custom_metrc_manifest_number || "—", frm.doc.custom_metrc_transfer_id]
						),
					});
				},
				__("METRC")
			);
		}
	},
});
